#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_key_is_translated_in_both_languages() {
        for &lang in Lang::ALL {
            for &key in Key::ALL {
                assert!(
                    !get(lang, key).is_empty(),
                    "{} has no copy for {}",
                    key.name(),
                    lang.code()
                );
                assert_eq!(
                    Key::parse(key.name()),
                    Some(key),
                    "{} does not round-trip",
                    key.name()
                );
            }
        }
    }
}
